<?php
declare(strict_types=1);
namespace Titan\BookingIntegration;
/** Independent persisted readback, no success flags generated by the caller. */
final class LifecycleMutationAudit {
 public static function reschedule(\PDO $db,int $id,array $before,array $move,array $siblings,array $order):array {
  $after=LifecycleFullBookingReader::read($db,$id);
  LifecycleImmutableIdentity::verify($before,$after);
  LifecycleMutationStatus::rescheduled($before,$after);
  LifecycleMutationClock::reschedule($after,$move);
  LifecycleMutationStaff::reschedule($after,$move);
  LifecycleSiblingIntegrity::verify($siblings,LifecycleSiblingReader::read($db,$after['order_id'],$id));
  LifecycleOrderIntegrity::verify($order,LifecycleClientOrderReader::read($db,$after['order_id']));
  return $after;
 }
 public static function cancel(\PDO $db,int $id,array $before,array $siblings,array $order):array {
  $after=LifecycleFullBookingReader::read($db,$id);
  LifecycleImmutableIdentity::verify($before,$after);
  LifecycleMutationStatus::cancelled($before,$after);
  LifecycleMutationClock::cancellation($before,$after);
  LifecycleMutationStaff::cancellation($before,$after);
  LifecycleSiblingIntegrity::verify($siblings,LifecycleSiblingReader::read($db,$after['order_id'],$id));
  LifecycleOrderIntegrity::verify($order,LifecycleClientOrderReader::read($db,$after['order_id']));
  return $after;
 }
}
